    for k14 in [0..friend_h.length) {
      X := friend_1[k14];
      Y := friend_2[k14];
      x15 := friend_h[k14];
      for k16 in [0..smokes_h.length) {
        if smokes_1[k16] == Y {
          x17 := smokes_h[k16];
          c18 := false;
          g19 := false;
          for k20 in [0..coins3_c.length) { if coins3_1[k20] == X && coins3_2[k20] == Y { c18 = coins3_c[k20]; g19 = true; } }
          if !g19 { c18 = flip(0.2); coins3_1 = coins3_1 ~ [X]; coins3_2 = coins3_2 ~ [Y]; coins3_c = coins3_c ~ [c18]; }
          v21 := x15 && x17 && c18;
          f22 := false;
          for k23 in [0..next_smokes_h.length) {
            if next_smokes_1[k23] == X { next_smokes_h[k23] = next_smokes_h[k23] || v21; f22 = true; }
          }
          if !f22 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v21]; }
        }
      }
    }
    smokes_1 = next_smokes_1;
    smokes_h = next_smokes_h;
    stage7 = stage7 + 1;
  }

