// problogex_3_tossing_coin.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // the symbols as numbers: c1 1000000, c2 1000001, c3 1000002, c4 1000003
  // coin/1: 4 facts
  coin_facts_1 := [1000000, 1000001, 1000002, 1000003]: ℤ[];
  coin_facts_p := [1.0, 1.0, 1.0, 1.0]: ℝ[];
  coin_facts_h := array(coin_facts_p.length, false);
  for i in [0..coin_facts_p.length) { if coin_facts_p[i] < 1 { coin_facts_h[i] = flip(coin_facts_p[i]); } else { coin_facts_h[i] = true; } }

  coin_1 := coin_facts_1;
  coin_h := coin_facts_h;

  heads_1 := []: ℤ[];
  heads_h := []: 𝔹[];
  // 0.6::heads(C) :- coin(C).
  for k1 in [0..coin_h.length) {
    C := coin_1[k1];
    x2 := coin_h[k1];
    c3 := flip(0.6);
    v4 := x2 && c3;
    f5 := false;
    for k6 in [0..heads_h.length) {
      if heads_1[k6] == C { heads_h[k6] = heads_h[k6] || v4; f5 = true; }
    }
    if !f5 { heads_1 = heads_1 ~ [C]; heads_h = heads_h ~ [v4]; }
  }

  someHeads_h := []: 𝔹[];
  // someHeads :- heads(_).
  for k7 in [0..heads_h.length) {
    x8 := heads_h[k7];
    v9 := x8;
    f10 := false;
    for k11 in [0..someHeads_h.length) {
      if true { someHeads_h[k11] = someHeads_h[k11] || v9; f10 = true; }
    }
    if !f10 { someHeads_h = someHeads_h ~ [v9]; }
  }

  q12 := false;
  for q12_k in [0..someHeads_h.length) { if true { q12 = someHeads_h[q12_k]; } }
  queries := [q12];
  return queries[0];
}

