// problogex_negation.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // a/0: 1 facts
  a_facts_p := [0.2]: ℝ[];
  a_facts_h := array(a_facts_p.length, false);
  for i in [0..a_facts_p.length) { if a_facts_p[i] < 1 { a_facts_h[i] = flip(a_facts_p[i]); } else { a_facts_h[i] = true; } }
  // b/0: 1 facts
  b_facts_p := [0.7]: ℝ[];
  b_facts_h := array(b_facts_p.length, false);
  for i in [0..b_facts_p.length) { if b_facts_p[i] < 1 { b_facts_h[i] = flip(b_facts_p[i]); } else { b_facts_h[i] = true; } }

  a_h := a_facts_h;

  b_h := b_facts_h;

  c_h := []: 𝔹[];
  // c :- a, b.
  for k1 in [0..a_h.length) {
    x2 := a_h[k1];
    for k3 in [0..b_h.length) {
      x4 := b_h[k3];
      v5 := x2 && x4;
      f6 := false;
      for k7 in [0..c_h.length) {
        if true { c_h[k7] = c_h[k7] || v5; f6 = true; }
      }
      if !f6 { c_h = c_h ~ [v5]; }
    }
  }
  // c :- a, \+ b.
  n8 := false;
  for k9 in [0..b_h.length) { if true { n8 = n8 || b_h[k9]; } }
  for k10 in [0..a_h.length) {
    x11 := a_h[k10];
    v12 := !n8 && x11;
    f13 := false;
    for k14 in [0..c_h.length) {
      if true { c_h[k14] = c_h[k14] || v12; f13 = true; }
    }
    if !f13 { c_h = c_h ~ [v12]; }
  }

  q1__h := []: 𝔹[];
  // q1 :- b, c.
  for k15 in [0..b_h.length) {
    x16 := b_h[k15];
    for k17 in [0..c_h.length) {
      x18 := c_h[k17];
      v19 := x16 && x18;
      f20 := false;
      for k21 in [0..q1__h.length) {
        if true { q1__h[k21] = q1__h[k21] || v19; f20 = true; }
      }
      if !f20 { q1__h = q1__h ~ [v19]; }
    }
  }

  q2__h := []: 𝔹[];
  // q2 :- \+ b, c.
  n22 := false;
  for k23 in [0..b_h.length) { if true { n22 = n22 || b_h[k23]; } }
  for k24 in [0..c_h.length) {
    x25 := c_h[k24];
    v26 := !n22 && x25;
    f27 := false;
    for k28 in [0..q2__h.length) {
      if true { q2__h[k28] = q2__h[k28] || v26; f27 = true; }
    }
    if !f27 { q2__h = q2__h ~ [v26]; }
  }

  q29 := false;
  for q29_k in [0..q1__h.length) { if true { q29 = q1__h[q29_k]; } }
  q30 := false;
  for q30_k in [0..q2__h.length) { if true { q30 = q2__h[q30_k]; } }
  queries := [q29, q30];
  return queries[1];
}

