  for k24 in [0..smokes_h.length) {
    X := smokes_1[k24];
    x25 := smokes_h[k24];
    c26 := flip(0.4);
    v27 := x25 && c26;
    f28 := false;
    for k29 in [0..asthma_h.length) {
      if asthma_1[k29] == X { asthma_h[k29] = asthma_h[k29] || v27; f28 = true; }
    }
    if !f28 { asthma_1 = asthma_1 ~ [X]; asthma_h = asthma_h ~ [v27]; }
  }

  q30 := false;
  for q30_k in [0..smokes_h.length) { if smokes_1[q30_k] == 1 { q30 = smokes_h[q30_k]; } }
  q31 := false;
  for q31_k in [0..smokes_h.length) { if smokes_1[q31_k] == 2 { q31 = smokes_h[q31_k]; } }
  q32 := false;
  for q32_k in [0..smokes_h.length) { if smokes_1[q32_k] == 3 { q32 = smokes_h[q32_k]; } }
  q33 := false;
  for q33_k in [0..smokes_h.length) { if smokes_1[q33_k] == 4 { q33 = smokes_h[q33_k]; } }
  q34 := false;
  for q34_k in [0..asthma_h.length) { if asthma_1[q34_k] == 1 { q34 = asthma_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..asthma_h.length) { if asthma_1[q35_k] == 2 { q35 = asthma_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..asthma_h.length) { if asthma_1[q36_k] == 3 { q36 = asthma_h[q36_k]; } }
  q37 := false;
  for q37_k in [0..asthma_h.length) { if asthma_1[q37_k] == 4 { q37 = asthma_h[q37_k]; } }
  e38 := false;
  for e38_k in [0..smokes_h.length) { if smokes_1[e38_k] == 2 { e38 = smokes_h[e38_k]; } }
  observe(e38);
  queries := [q30, q31, q32, q33, q34, q35, q36, q37];
  return queries[2];
}

texts.48414a9b2c16a606827d33b2bd7c934eaf696173:
// problogex_add.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {

  p_1 := []: ℤ[];
  p_h := []: 𝔹[];
  // 0.3::p(1); 0.4::p(2).
  c1 := categorical([0.3, 0.4, 1 - 0.3 - 0.4]);
  v2 := c1 == 0;
  f3 := false;
  for k4 in [0..p_h.length) {
    if p_1[k4] == 1 { p_h[k4] = p_h[k4] || v2; f3 = true; }
  }
  if !f3 { p_1 = p_1 ~ [1]; p_h = p_h ~ [v2]; }
  v5 := c1 == 1;
  f6 := false;
  for k7 in [0..p_h.length) {
    if p_1[k7] == 2 { p_h[k7] = p_h[k7] || v5; f6 = true; }
  }
  if !f6 { p_1 = p_1 ~ [2]; p_h = p_h ~ [v5]; }

  all_h := []: 𝔹[];
  // all :- p(1), p(2).
  for k8 in [0..p_h.length) {
    if p_1[k8] == 1 {
      x9 := p_h[k8];
      for k10 in [0..p_h.length) {
        if p_1[k10] == 2 {
          x11 := p_h[k10];
          v12 := x9 && x11;
          f13 := false;
          for k14 in [0..all_h.length) {
            if true { all_h[k14] = all_h[k14] || v12; f13 = true; }
          }
          if !f13 { all_h = all_h ~ [v12]; }
        }
      }
    }
  }

  any_h := []: 𝔹[];
  // any :- p(1).
  for k15 in [0..p_h.length) {
    if p_1[k15] == 1 {
      x16 := p_h[k15];
      v17 := x16;
      f18 := false;
      for k19 in [0..any_h.length) {
        if true { any_h[k19] = any_h[k19] || v17; f18 = true; }
      }
      if !f18 { any_h = any_h ~ [v17]; }
    }
  }
  // any :- p(2).
  for k20 in [0..p_h.length) {
    if p_1[k20] == 2 {
      x21 := p_h[k20];
      v22 := x21;
      f23 := false;
      for k24 in [0..any_h.length) {
        if true { any_h[k24] = any_h[k24] || v22; f23 = true; }
      }
      if !f23 { any_h = any_h ~ [v22]; }
    }
  }

  none_h := []: 𝔹[];
  // none :- \+ p(1), \+ p(2).
  n25 := false;
