    if !f13 { stress_1 = stress_1 ~ [X]; stress_h = stress_h ~ [v12]; }
  }

  // smokes/1: recursive; the rules applied in stages from no tuple,
  // each reading the stage before, until a stage adds no tuple and the stages number the tuples
  smokes_1 := []: ℤ[];
  smokes_h := []: 𝔹[];
  stage15 := 0;
  before16 := -1;
  while stage15 < smokes_h.length || smokes_h.length != before16 {
    before16 = smokes_h.length;
    next_smokes_1 := []: ℤ[];
    next_smokes_h := []: 𝔹[];
    // smokes(X) :- stress(X).
    for k17 in [0..stress_h.length) {
      X := stress_1[k17];
      x18 := stress_h[k17];
      v19 := x18;
      f20 := false;
      for k21 in [0..next_smokes_h.length) {
        if next_smokes_1[k21] == X { next_smokes_h[k21] = next_smokes_h[k21] || v19; f20 = true; }
      }
      if !f20 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v19]; }
    }
    // smokes(X) :- friend(X,Y), influences(Y,X), smokes(Y).
    for k22 in [0..friend_h.length) {
      X := friend_1[k22];
      Y := friend_2[k22];
      x23 := friend_h[k22];
      for k24 in [0..influences_h.length) {
        if influences_1[k24] == Y && influences_2[k24] == X {
          x25 := influences_h[k24];
          for k26 in [0..smokes_h.length) {
            if smokes_1[k26] == Y {
              x27 := smokes_h[k26];
              v28 := x23 && x25 && x27;
              f29 := false;
              for k30 in [0..next_smokes_h.length) {
                if next_smokes_1[k30] == X { next_smokes_h[k30] = next_smokes_h[k30] || v28; f29 = true; }
              }
              if !f29 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v28]; }
            }
          }
        }
      }
    }
    smokes_1 = next_smokes_1;
    smokes_h = next_smokes_h;
    stage15 = stage15 + 1;
  }

  asthma_1 := []: ℤ[];
  asthma_h := []: 𝔹[];
  // 0.4::asthma(X) :- smokes(X).
  for k31 in [0..smokes_h.length) {
    X := smokes_1[k31];
    x32 := smokes_h[k31];
    c33 := flip(0.4);
    v34 := x32 && c33;
    f35 := false;
    for k36 in [0..asthma_h.length) {
      if asthma_1[k36] == X { asthma_h[k36] = asthma_h[k36] || v34; f35 = true; }
    }
    if !f35 { asthma_1 = asthma_1 ~ [X]; asthma_h = asthma_h ~ [v34]; }
  }

  q37 := false;
  for q37_k in [0..smokes_h.length) { if smokes_1[q37_k] == 1 { q37 = smokes_h[q37_k]; } }
  q38 := false;
  for q38_k in [0..smokes_h.length) { if smokes_1[q38_k] == 2 { q38 = smokes_h[q38_k]; } }
  q39 := false;
  for q39_k in [0..smokes_h.length) { if smokes_1[q39_k] == 3 { q39 = smokes_h[q39_k]; } }
  q40 := false;
  for q40_k in [0..smokes_h.length) { if smokes_1[q40_k] == 4 { q40 = smokes_h[q40_k]; } }
  q41 := false;
  for q41_k in [0..asthma_h.length) { if asthma_1[q41_k] == 1 { q41 = asthma_h[q41_k]; } }
  q42 := false;
  for q42_k in [0..asthma_h.length) { if asthma_1[q42_k] == 2 { q42 = asthma_h[q42_k]; } }
  q43 := false;
  for q43_k in [0..asthma_h.length) { if asthma_1[q43_k] == 3 { q43 = asthma_h[q43_k]; } }
  q44 := false;
  for q44_k in [0..asthma_h.length) { if asthma_1[q44_k] == 4 { q44 = asthma_h[q44_k]; } }
  e45 := false;
  for e45_k in [0..smokes_h.length) { if smokes_1[e45_k] == 2 { e45 = smokes_h[e45_k]; } }
  e46 := false;
  for e46_k in [0..influences_h.length) { if influences_1[e46_k] == 4 && influences_2[e46_k] == 2 { e46 = influences_h[e46_k]; } }
  observe(e45 && !e46);
  queries := [q37, q38, q39, q40, q41, q42, q43, q44];
  return queries[1];
}

