var position_facts = relationOfFacts(lpFacts['position/1'] || []);

var position = position_facts;

var instances_card = [].concat(
  // 0.25::card(C,q,h); 0.25::card(C,k,h); 0.25::card(C,q,s); 0.25::card(C,k,s) :- position(C).
  (function() {
