// problogex_coin.pl: a ProbLog program written in Psi by tddlog's scripts/problog2ppl.py,
// first order as it is written. A relation is a column of integers for each
// argument and a column of Booleans for whether each tuple holds, a symbol a
// number of its own; each probabilistic fact is a coin of its own (`flip`), the
// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // heads1/0: 1 facts
  heads1_facts_p := [0.5]: ℝ[];
  heads1_facts_h := array(heads1_facts_p.length, false);
  for i in [0..heads1_facts_p.length) { if heads1_facts_p[i] < 1 { heads1_facts_h[i] = flip(heads1_facts_p[i]); } else { heads1_facts_h[i] = true; } }
  // heads2/0: 1 facts
  heads2_facts_p := [0.6]: ℝ[];
  heads2_facts_h := array(heads2_facts_p.length, false);
  for i in [0..heads2_facts_p.length) { if heads2_facts_p[i] < 1 { heads2_facts_h[i] = flip(heads2_facts_p[i]); } else { heads2_facts_h[i] = true; } }

  heads1_h := heads1_facts_h;

  heads2_h := heads2_facts_h;

  someHeads_h := []: 𝔹[];
  // someHeads :- heads1.
  for k1 in [0..heads1_h.length) {
    x2 := heads1_h[k1];
    v3 := x2;
    f4 := false;
    for k5 in [0..someHeads_h.length) {
      if true { someHeads_h[k5] = someHeads_h[k5] || v3; f4 = true; }
    }
    if !f4 { someHeads_h = someHeads_h ~ [v3]; }
  }
  // someHeads :- heads2.
  for k6 in [0..heads2_h.length) {
    x7 := heads2_h[k6];
    v8 := x7;
    f9 := false;
    for k10 in [0..someHeads_h.length) {
      if true { someHeads_h[k10] = someHeads_h[k10] || v8; f9 = true; }
    }
    if !f9 { someHeads_h = someHeads_h ~ [v8]; }
  }

  twoHeads_h := []: 𝔹[];
  // twoHeads :- heads1, heads2.
  for k11 in [0..heads1_h.length) {
    x12 := heads1_h[k11];
    for k13 in [0..heads2_h.length) {
      x14 := heads2_h[k13];
      v15 := x12 && x14;
      f16 := false;
      for k17 in [0..twoHeads_h.length) {
        if true { twoHeads_h[k17] = twoHeads_h[k17] || v15; f16 = true; }
      }
      if !f16 { twoHeads_h = twoHeads_h ~ [v15]; }
    }
  }

  q18 := false;
  for q18_k in [0..someHeads_h.length) { if true { q18 = someHeads_h[q18_k]; } }
  q19 := false;
  for q19_k in [0..twoHeads_h.length) { if true { q19 = twoHeads_h[q19_k]; } }
  queries := [q18, q19];
