// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // edge/2: 7 facts
  edge_facts_1 := [1, 1, 2, 2, 3, 4, 5]: ℤ[];
  edge_facts_2 := [2, 3, 5, 6, 4, 5, 6]: ℤ[];
  edge_facts_p := [0.6, 0.1, 0.4, 0.3, 0.3, 0.8, 0.2]: ℝ[];
