  for i in [0..edge_facts_p.length) { if edge_facts_p[i] < 1 { edge_facts_h[i] = flip(edge_facts_p[i]); } else { edge_facts_h[i] = true; } }

  edge_1 := edge_facts_1;
  edge_2 := edge_facts_2;
  edge_h := edge_facts_h;

  // path/2: recursive; the rules applied in stages from no tuple,
  // each reading the stage before, until a stage adds no tuple and the stages number the tuples
  path_1 := []: ℤ[];
  path_2 := []: ℤ[];
  path_h := []: 𝔹[];
  stage1 := 0;
  before2 := -1;
  while stage1 < path_h.length || path_h.length != before2 {
    before2 = path_h.length;
    next_path_1 := []: ℤ[];
    next_path_2 := []: ℤ[];
    next_path_h := []: 𝔹[];
    // path(X,Y) :- edge(X,Y).
    for k3 in [0..edge_h.length) {
