      f6 := false;
      for k7 in [0..next_path_h.length) {
        if next_path_1[k7] == X && next_path_2[k7] == Y { next_path_h[k7] = next_path_h[k7] || v5; f6 = true; }
      }
      if !f6 { next_path_1 = next_path_1 ~ [X]; next_path_2 = next_path_2 ~ [Y]; next_path_h = next_path_h ~ [v5]; }
    }
    // path(X,Y) :- edge(X,Z), Y \== Z, path(Z,Y).
    for k8 in [0..edge_h.length) {
      X := edge_1[k8];
      Z := edge_2[k8];
      x9 := edge_h[k8];
      for k10 in [0..path_h.length) {
        if path_1[k10] == Z {
          Y := path_2[k10];
          x11 := path_h[k10];
          if Y != Z {
            v12 := x9 && x11;
            f13 := false;
            for k14 in [0..next_path_h.length) {
              if next_path_1[k14] == X && next_path_2[k14] == Y { next_path_h[k14] = next_path_h[k14] || v12; f13 = true; }
            }
            if !f13 { next_path_1 = next_path_1 ~ [X]; next_path_2 = next_path_2 ~ [Y]; next_path_h = next_path_h ~ [v12]; }
          }
        }
      }
    }
    path_1 = next_path_1;
    path_2 = next_path_2;
    path_h = next_path_h;
    stage1 = stage1 + 1;
  }

  q15 := false;
  for q15_k in [0..path_h.length) { if path_1[q15_k] == 1 && path_2[q15_k] == 5 { q15 = path_h[q15_k]; } }
  q16 := false;
  for q16_k in [0..path_h.length) { if path_1[q16_k] == 1 && path_2[q16_k] == 6 { q16 = path_h[q16_k]; } }
  queries := [q15, q16];
  return queries[1];
}

