  v5 := c1 == 1;
  f6 := false;
  for k7 in [0..p_h.length) {
    if p_1[k7] == 2 { p_h[k7] = p_h[k7] || v5; f6 = true; }
  }
  if !f6 { p_1 = p_1 ~ [2]; p_h = p_h ~ [v5]; }

  all_h := []: 𝔹[];
  // all :- p(1), p(2).
  for k8 in [0..p_h.length) {
    if p_1[k8] == 1 {
      x9 := p_h[k8];
      for k10 in [0..p_h.length) {
        if p_1[k10] == 2 {
          x11 := p_h[k10];
          v12 := x9 && x11;
          f13 := false;
          for k14 in [0..all_h.length) {
            if true { all_h[k14] = all_h[k14] || v12; f13 = true; }
          }
          if !f13 { all_h = all_h ~ [v12]; }
        }
      }
    }
  }

  any_h := []: 𝔹[];
  // any :- p(1).
  for k15 in [0..p_h.length) {
    if p_1[k15] == 1 {
      x16 := p_h[k15];
      v17 := x16;
      f18 := false;
      for k19 in [0..any_h.length) {
        if true { any_h[k19] = any_h[k19] || v17; f18 = true; }
      }
      if !f18 { any_h = any_h ~ [v17]; }
    }
  }
  // any :- p(2).
  for k20 in [0..p_h.length) {
    if p_1[k20] == 2 {
      x21 := p_h[k20];
      v22 := x21;
      f23 := false;
      for k24 in [0..any_h.length) {
        if true { any_h[k24] = any_h[k24] || v22; f23 = true; }
      }
      if !f23 { any_h = any_h ~ [v22]; }
    }
  }

  none_h := []: 𝔹[];
  // none :- \+ p(1), \+ p(2).
  n25 := false;
  for k26 in [0..p_h.length) { if p_1[k26] == 1 { n25 = n25 || p_h[k26]; } }
  n27 := false;
  for k28 in [0..p_h.length) { if p_1[k28] == 2 { n27 = n27 || p_h[k28]; } }
  v29 := !n25 && !n27;
  f30 := false;
  for k31 in [0..none_h.length) {
    if true { none_h[k31] = none_h[k31] || v29; f30 = true; }
  }
  if !f30 { none_h = none_h ~ [v29]; }

  q32 := false;
  for q32_k in [0..p_h.length) { if p_1[q32_k] == 1 { q32 = p_h[q32_k]; } }
  q33 := false;
  for q33_k in [0..p_h.length) { if p_1[q33_k] == 2 { q33 = p_h[q33_k]; } }
  q34 := false;
  for q34_k in [0..all_h.length) { if true { q34 = all_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..none_h.length) { if true { q35 = none_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..any_h.length) { if true { q36 = any_h[q36_k]; } }
  queries := [q32, q33, q34, q35, q36];
