// facts arrays in the program; each rule is a loop over the relations its body
// joins, a tuple looked up by a scan. The value is the array of the queries'
// holdings, given the evidence (`observe`): one is asked a run, its `return`
// made `return queries[K];`.
//
//   psi --dp PROGRAM.psi
def main() {
  // burglary/0: 1 facts
  burglary_facts_p := [0.7]: ℝ[];
  burglary_facts_h := array(burglary_facts_p.length, false);
  for i in [0..burglary_facts_p.length) { if burglary_facts_p[i] < 1 { burglary_facts_h[i] = flip(burglary_facts_p[i]); } else { burglary_facts_h[i] = true; } }
  // earthquake/0: 1 facts
  earthquake_facts_p := [0.2]: ℝ[];
  earthquake_facts_h := array(earthquake_facts_p.length, false);
  for i in [0..earthquake_facts_p.length) { if earthquake_facts_p[i] < 1 { earthquake_facts_h[i] = flip(earthquake_facts_p[i]); } else { earthquake_facts_h[i] = true; } }
  // p_alarm1/0: 1 facts
  p_alarm1_facts_p := [0.9]: ℝ[];
  p_alarm1_facts_h := array(p_alarm1_facts_p.length, false);
  for i in [0..p_alarm1_facts_p.length) { if p_alarm1_facts_p[i] < 1 { p_alarm1_facts_h[i] = flip(p_alarm1_facts_p[i]); } else { p_alarm1_facts_h[i] = true; } }
  // p_alarm2/0: 1 facts
