  p_alarm2_facts_h := array(p_alarm2_facts_p.length, false);
  for i in [0..p_alarm2_facts_p.length) { if p_alarm2_facts_p[i] < 1 { p_alarm2_facts_h[i] = flip(p_alarm2_facts_p[i]); } else { p_alarm2_facts_h[i] = true; } }
  // p_alarm3/0: 1 facts
  p_alarm3_facts_p := [0.1]: ℝ[];
  p_alarm3_facts_h := array(p_alarm3_facts_p.length, false);
  for i in [0..p_alarm3_facts_p.length) { if p_alarm3_facts_p[i] < 1 { p_alarm3_facts_h[i] = flip(p_alarm3_facts_p[i]); } else { p_alarm3_facts_h[i] = true; } }

  burglary_h := burglary_facts_h;

  earthquake_h := earthquake_facts_h;

  p_alarm1_h := p_alarm1_facts_h;

  p_alarm2_h := p_alarm2_facts_h;

  p_alarm3_h := p_alarm3_facts_h;

  alarm_h := []: 𝔹[];
  // alarm :- burglary, earthquake, p_alarm1.
  for k1 in [0..burglary_h.length) {
    x2 := burglary_h[k1];
    for k3 in [0..earthquake_h.length) {
      x4 := earthquake_h[k3];
      for k5 in [0..p_alarm1_h.length) {
        x6 := p_alarm1_h[k5];
        v7 := x2 && x4 && x6;
        f8 := false;
        for k9 in [0..alarm_h.length) {
          if true { alarm_h[k9] = alarm_h[k9] || v7; f8 = true; }
        }
        if !f8 { alarm_h = alarm_h ~ [v7]; }
      }
    }
  }
  // alarm :- burglary, \+ earthquake, p_alarm2.
  n10 := false;
  for k11 in [0..earthquake_h.length) { if true { n10 = n10 || earthquake_h[k11]; } }
  for k12 in [0..burglary_h.length) {
    x13 := burglary_h[k12];
    for k14 in [0..p_alarm2_h.length) {
      x15 := p_alarm2_h[k14];
      v16 := !n10 && x13 && x15;
      f17 := false;
      for k18 in [0..alarm_h.length) {
        if true { alarm_h[k18] = alarm_h[k18] || v16; f17 = true; }
      }
      if !f17 { alarm_h = alarm_h ~ [v16]; }
    }
  }
  // alarm :- \+ burglary, earthquake, p_alarm3.
  n19 := false;
  for k20 in [0..burglary_h.length) { if true { n19 = n19 || burglary_h[k20]; } }
  for k21 in [0..earthquake_h.length) {
    x22 := earthquake_h[k21];
    for k23 in [0..p_alarm3_h.length) {
      x24 := p_alarm3_h[k23];
      v25 := !n19 && x22 && x24;
      f26 := false;
      for k27 in [0..alarm_h.length) {
        if true { alarm_h[k27] = alarm_h[k27] || v25; f26 = true; }
      }
      if !f26 { alarm_h = alarm_h ~ [v25]; }
    }
  }

  q28 := false;
  for q28_k in [0..burglary_h.length) { if true { q28 = burglary_h[q28_k]; } }
  q29 := false;
  for q29_k in [0..earthquake_h.length) { if true { q29 = earthquake_h[q29_k]; } }
  e30 := false;
  for e30_k in [0..alarm_h.length) { if true { e30 = alarm_h[e30_k]; } }
  observe(e30);
  queries := [q28, q29];
  return queries[0];
}

