  coins2_2 := []: ℤ[];
  coins2_c := []: ℕ[];
  // the draws of `0.2::weather(sun,T); 0.8::weather(rain,T) :- demand_3(T), T > 0, Tprev is T - 1, weather(rain,Tprev).`, by instance
