      Y := person_1[k3];
      x4 := person_h[k3];
      c5 := flip(0.2);
      v6 := x2 && x4 && c5;
      f7 := false;
      for k8 in [0..influences_h.length) {
        if influences_1[k8] == X && influences_2[k8] == Y { influences_h[k8] = influences_h[k8] || v6; f7 = true; }
      }
      if !f7 { influences_1 = influences_1 ~ [X]; influences_2 = influences_2 ~ [Y]; influences_h = influences_h ~ [v6]; }
