      X := friend_1[k22];
      Y := friend_2[k22];
      x23 := friend_h[k22];
      for k24 in [0..influences_h.length) {
        if influences_1[k24] == Y && influences_2[k24] == X {
          x25 := influences_h[k24];
          for k26 in [0..smokes_h.length) {
            if smokes_1[k26] == Y {
              x27 := smokes_h[k26];
              v28 := x23 && x25 && x27;
              f29 := false;
              for k30 in [0..next_smokes_h.length) {
                if next_smokes_1[k30] == X { next_smokes_h[k30] = next_smokes_h[k30] || v28; f29 = true; }
              }
              if !f29 { next_smokes_1 = next_smokes_1 ~ [X]; next_smokes_h = next_smokes_h ~ [v28]; }
            }
          }
        }
      }
    }
    smokes_1 = next_smokes_1;
    smokes_h = next_smokes_h;
