    }
    if !f35 { asthma_1 = asthma_1 ~ [X]; asthma_h = asthma_h ~ [v34]; }
  }

  q37 := false;
  for q37_k in [0..smokes_h.length) { if smokes_1[q37_k] == 1 { q37 = smokes_h[q37_k]; } }
  q38 := false;
  for q38_k in [0..smokes_h.length) { if smokes_1[q38_k] == 2 { q38 = smokes_h[q38_k]; } }
  q39 := false;
  for q39_k in [0..smokes_h.length) { if smokes_1[q39_k] == 3 { q39 = smokes_h[q39_k]; } }
  q40 := false;
  for q40_k in [0..smokes_h.length) { if smokes_1[q40_k] == 4 { q40 = smokes_h[q40_k]; } }
  q41 := false;
  for q41_k in [0..asthma_h.length) { if asthma_1[q41_k] == 1 { q41 = asthma_h[q41_k]; } }
  q42 := false;
  for q42_k in [0..asthma_h.length) { if asthma_1[q42_k] == 2 { q42 = asthma_h[q42_k]; } }
  q43 := false;
  for q43_k in [0..asthma_h.length) { if asthma_1[q43_k] == 3 { q43 = asthma_h[q43_k]; } }
  q44 := false;
  for q44_k in [0..asthma_h.length) { if asthma_1[q44_k] == 4 { q44 = asthma_h[q44_k]; } }
  e45 := false;
  for e45_k in [0..smokes_h.length) { if smokes_1[e45_k] == 2 { e45 = smokes_h[e45_k]; } }
  e46 := false;
  for e46_k in [0..influences_h.length) { if influences_1[e46_k] == 4 && influences_2[e46_k] == 2 { e46 = influences_h[e46_k]; } }
