  for k8 in [0..p_h.length) {
    if p_1[k8] == 1 {
      x9 := p_h[k8];
      for k10 in [0..p_h.length) {
        if p_1[k10] == 2 {
          x11 := p_h[k10];
          v12 := x9 && x11;
          f13 := false;
          for k14 in [0..all_h.length) {
            if true { all_h[k14] = all_h[k14] || v12; f13 = true; }
          }
          if !f13 { all_h = all_h ~ [v12]; }
        }
      }
    }
  }

  any_h := []: 𝔹[];
  // any :- p(1).
  for k15 in [0..p_h.length) {
    if p_1[k15] == 1 {
      x16 := p_h[k15];
      v17 := x16;
      f18 := false;
      for k19 in [0..any_h.length) {
        if true { any_h[k19] = any_h[k19] || v17; f18 = true; }
      }
      if !f18 { any_h = any_h ~ [v17]; }
    }
  }
  // any :- p(2).
  for k20 in [0..p_h.length) {
    if p_1[k20] == 2 {
      x21 := p_h[k20];
      v22 := x21;
      f23 := false;
      for k24 in [0..any_h.length) {
        if true { any_h[k24] = any_h[k24] || v22; f23 = true; }
      }
      if !f23 { any_h = any_h ~ [v22]; }
    }
  }

  none_h := []: 𝔹[];
