  for k26 in [0..p_h.length) { if p_1[k26] == 1 { n25 = n25 || p_h[k26]; } }
  n27 := false;
  for k28 in [0..p_h.length) { if p_1[k28] == 2 { n27 = n27 || p_h[k28]; } }
  v29 := !n25 && !n27;
  f30 := false;
  for k31 in [0..none_h.length) {
    if true { none_h[k31] = none_h[k31] || v29; f30 = true; }
  }
  if !f30 { none_h = none_h ~ [v29]; }

  q32 := false;
  for q32_k in [0..p_h.length) { if p_1[q32_k] == 1 { q32 = p_h[q32_k]; } }
  q33 := false;
  for q33_k in [0..p_h.length) { if p_1[q33_k] == 2 { q33 = p_h[q33_k]; } }
  q34 := false;
  for q34_k in [0..all_h.length) { if true { q34 = all_h[q34_k]; } }
  q35 := false;
  for q35_k in [0..none_h.length) { if true { q35 = none_h[q35_k]; } }
  q36 := false;
  for q36_k in [0..any_h.length) { if true { q36 = any_h[q36_k]; } }
  queries := [q32, q33, q34, q35, q36];
  return queries[2];
}

